const url = $json.message.text.replace("/learn ", "");
let urlError = undefined;
if (!url) {
  urlError = "no_valid"
}
return [{ json: { ...$json, url: url, urlError } }];

const rawData = $json.data || $json.body || '';
const content = typeof rawData === 'string' ? rawData : JSON.stringify(rawData);
const wordCount = content.trim().split(/\s+/).filter(w => w.length > 0).length;
let contentError = null;
if (wordCount < 100) {
  contentError = 'insufficient_content';
} else {
  const lower = content.toLowerCase();
  const paywallSignals = ['sign in to continue', 'subscribe to read', 'login required', 'access denied'];
  if (paywallSignals.some(s => lower.includes(s)) && wordCount < 300) {
    contentError = 'paywall_detected';
  }
}
const url = $('Validate URL').first().json.url;
const chatId = $('Extract Message Fields').first().json.chatId;
const userId = $('Extract Message Fields').first().json.userId;
return [{ json: { url, chatId, userId, content: content.slice(0, 50000), contentError } }];

const p = $json;
const url = $('Validate URL').first().json.url;
const chatId = $('Extract Message Fields').first().json.message.chat.id;
const userId = $('Extract Message Fields').first().json.message.from.id;
const content = $('Truncate Content').first().json.content;
const points = (p.summary_points || []).map((pt, i) => `${i+1}. ${pt}`).join('\n');
const concepts = (p.main_concepts || []).join(', ');
const diffEmoji = { beginner: '🟢', intermediate: '🟡', advanced: '🔴' };
const diff = p.difficulty || 'unknown';
const emoji = diffEmoji[diff] || '⚪';
const diffLabel = diff.charAt(0).toUpperCase() + diff.slice(1);
const message = `📚 <b>${p.title}</b>\n\n<b>Key Points:</b>\n${points}\n\n<b>Main Concepts:</b> ${concepts}\n\n${emoji} <b>Difficulty:</b> ${diffLabel}\n\nReady to test your knowledge? Type /quiz anytime!`;
return [{ json: { url, chatId, userId, content, title: p.title, summary: JSON.stringify(p.summary_points), mainConcepts: concepts, difficulty: diff, message } }];

const rows = $input.all();
let userId, chatId;
try { const ctx = $('Extract Message Fields').first().json; userId = ctx.userId; chatId = ctx.chatId; } catch(e) {}
const validRows = rows.filter(r => r.json && r.json.id);
if (validRows.length === 0) {
  return [{ json: { route: 'none', userId, chatId } }];
}
if (validRows.length === 1) {
  const r = validRows[0].json;
  return [{ json: { route: 'single', materialId: r.id, title: r.title, summary: r.summary, content: r.content, userId, chatId } }];
}
return [{ json: { route: 'many', materials: validRows.map(r => ({ id: r.json.id, title: r.json.title })), userId, chatId } }];

const materials = $json.materials || [];
const rows = [];
for (let i = 0; i < materials.length; i += 2) {
  const row = [{ text: (materials[i].title || 'Topic').slice(0, 40), callback_data: 'TOPIC:' + materials[i].id }];
  if (materials[i+1]) row.push({ text: (materials[i+1].title || 'Topic').slice(0, 40), callback_data: 'TOPIC:' + materials[i+1].id });
  rows.push(row);
}
const keyboard = { inline_keyboard: rows };
return [{ json: { ...$json, replyMarkup: JSON.stringify(keyboard) } }];

const input = $input.first().json;
return [{ json: {
  materialId: input.materialId || input.currentMaterialId,
  userId: input.userId,
  chatId: input.chatId,
  title: input.title || null,
  summary: input.summary || null,
  content: input.content || null
} }];

const rows = $input.all();
let ctx = {};
try { ctx = $('Set Material for Quiz').first().json; } catch(e) {}
const materialId = ctx.materialId;
const userId = ctx.userId;
const chatId = ctx.chatId;
const questionRows = rows.filter(r => r.json && r.json.questionId);
const cached = questionRows.length >= 5;
return [{ json: { materialId, userId, chatId, questions: questionRows.map(r => r.json), cached } }];

const data = $input.first().json;
const questions = data.questions || [];
let materialId;
try { materialId = $('Set Material for Quiz').first().json.materialId; } catch(e) { materialId = data.materialId; }
return questions.map(q => ({
  json: {
    materialId,
    questionId: q.id,
    question: q.question,
    optionA: q.options.A,
    optionB: q.options.B,
    optionC: q.options.C,
    optionD: q.options.D,
    correctAnswer: q.correctAnswer,
    explanation: q.explanation
  }
}));

let materialId, userId, chatId;
try { const ctx = $('Set Material for Quiz').first().json; materialId = ctx.materialId; userId = ctx.userId; chatId = ctx.chatId; } catch(e) {}
return [{ json: { materialId, userId, chatId } }];

const q = $input.first().json;
const questionIndex = 0;
let chatId;
try { chatId = $('Telegram Trigger').first().json.message.chat.id; } catch(e) { chatId = q.chatId; }

let text = `🧠 <b>Question ${questionIndex + 1} of 5</b>\n\n${q.question}\n`;
text += `A) ${q.optionA}\n`;
text += `B) ${q.optionB}\n`;
text += `C) ${q.optionC}\n`;
text += `D) ${q.optionD}`;

const keyboard = JSON.stringify({
  inline_keyboard: [
    [
      { text: 'A) ' + q.optionA, callback_data: 'A' },
      { text: 'B) ' + q.optionB, callback_data: 'B' }
    ],
    [
      { text: 'C) ' + q.optionC, callback_data: 'C' },
      { text: 'D) ' + q.optionD, callback_data: 'D' }
    ]
  ]
});
return [{ json: { ...q, chatId, questionText: text, questionKeyboard: keyboard } }];

const rows = $input.all();
const session = rows.length > 0 ? rows[0].json : {};
const chatId = $('Extract Message Fields').first().json.chatId;
const userId = $('Extract Message Fields').first().json.userId;
const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000);
const lastActivity = new Date(session.lastActivity || 0);
const state = lastActivity < twoHoursAgo ? 'IDLE' : (session.state || 'IDLE');
const inQuiz = state === 'IN_QUIZ';
const materialId = session.currentMaterialId || '';
const questionIndex = parseInt(session.currentQuestionIndex || 0);
return [{ json: { inQuiz, state, materialId, questionIndex, userId, chatId } }];

const q = $input.first().json;
const questionIndex = parseInt($('Check Free Text State').first().json.questionIndex);
const chatId = $('Extract Message Fields').first().json.chatId;

if (!q.question || !q.optionA) {
  return [{ json: { chatId, questionText: '⚠️ Не удалось загрузить вопрос. Попробуй /quiz заново.', questionKeyboard: null } }];
}

let text = `🧠 <b>Question ${questionIndex + 1} of 5</b>\n\n${q.question}\n`;
text += `A) ${q.optionA}\n`;
text += `B) ${q.optionB}\n`;
text += `C) ${q.optionC}\n`;
text += `D) ${q.optionD}`;

const keyboard = {
  inline_keyboard: [
    [
      { text: 'A) ' + q.optionA, callback_data: 'A' },
      { text: 'B) ' + q.optionB, callback_data: 'B' }
    ],
    [
      { text: 'C) ' + q.optionC, callback_data: 'C' },
      { text: 'D) ' + q.optionD, callback_data: 'D' }
    ]
  ]
};

return [{ json: { chatId, questionText: text, questionKeyboard: keyboard } }];

const rows = $input.all();
const session = rows.length > 0 ? rows[0].json : {};
const cb = $('Extract Callback Fields').first().json;
const userId = cb.userId;
const chatId = cb.chatId;
const callbackData = cb.callbackData || '';
const callbackQueryId = cb.callbackQueryId;
const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000);
const lastActivity = new Date(session.lastActivity || 0);
const state = lastActivity < twoHoursAgo ? 'IDLE' : (session.state || 'IDLE');
const materialId = session.currentMaterialId || '';
const questionIndex = parseInt(session.currentQuestionIndex || 0);
if (callbackData.startsWith('TOPIC:')) {
  const topicMaterialId = callbackData.replace('TOPIC:', '');
  return [{ json: { route: 'topic_select', materialId: topicMaterialId, userId, chatId, callbackQueryId } }];
}
if (state === 'IN_QUIZ' && ['A','B','C','D'].includes(callbackData)) {
  return [{ json: { route: 'answer', materialId, questionIndex, userAnswer: callbackData, userId, chatId, callbackQueryId } }];
}
return [{ json: { route: 'ignore', userId, chatId, callbackQueryId } }];

const q = $input.first().json;
const userAnswer = $('Router: Update Type').first().json.callback_query.data;
const isCorrect = userAnswer === q.correctAnswer;
return [{ json: {
  isCorrect,
  'feedback': isCorrect ? "right" : "wrong",
} }];

const rows = $input.all();
const answers = rows.map(r => r.json);
const total = Math.min(answers.length, 5);
const recentAnswers = answers.slice(-5);
const correct = recentAnswers.filter(a => a.isCorrect === true || a.isCorrect === 'true' || a.isCorrect === 'TRUE').length;
const pct = total > 0 ? Math.round((correct / total) * 100) : 0;
const lines = recentAnswers.map(a => {
  const isOk = a.isCorrect === true || a.isCorrect === 'true' || a.isCorrect === 'TRUE';
  if (isOk) return `✅ ${a.questionId}: Correct`;
  return `❌ ${a.questionId}: You answered ${a.userAnswer}`;
});
const message = `🎉 <b>Quiz Complete!</b>\nScore: <b>${correct}/${total} (${pct}%)</b>\n\n${lines.join('\n\n')}\n\nType /quiz to try again or /learn [URL] to add new material!`;
return [{ json: { message } }];

const q = $input.first().json;
const nextIndex = $('Update Question Index').first().json.currentQuestionIndex + 1;
const chatId = $('Evaluate Answer').first().json.chatId;
let text = `🧠 <b>Question ${nextIndex} of 5</b>\n\n${q.question}\n`;
text += `A) ${q.optionA}\n`;
text += `B) ${q.optionB}\n`;
text += `C) ${q.optionC}\n`;
text += `D) ${q.optionD}`;
const keyboard = JSON.stringify({
  inline_keyboard: [
    [
      { text: 'A) ' + q.optionA, callback_data: 'A' },
      { text: 'B) ' + q.optionB, callback_data: 'B' }
    ],
    [
      { text: 'C) ' + q.optionC, callback_data: 'C' },
      { text: 'D) ' + q.optionD, callback_data: 'D' }
    ]
  ]
});
return [{ json: { chatId, questionText: text, questionKeyboard: keyboard } }];

const callbackData = $input.first().json.callbackData;
const materialId = callbackData.replace('STARTQUIZ:', '');
return [{ json: { ...$input.first().json, selectedMaterialId: materialId } }];
